def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    visited = [[False] * cols for _ in range(rows)]
    components = {}

    # Find all connected components
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                color = grid[r][c]
                comp = {(r, c)}
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            comp.add((nr, nc))
                            queue.append((nr, nc))

                if color not in components:
                    components[color] = set()
                components[color].update(comp)

    result = [row[:] for row in grid]

    # For each color component, modify interior to 8 (except "background" that touches all bounds)
    for color, cells in components.items():
        if not cells:
            continue

        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        # Skip background that touches all four boundaries
        if min_r == 0 and max_r == rows - 1 and min_c == 0 and max_c == cols - 1:
            continue

        # Change interior cells to 8
        for r, c in cells:
            if min_r < r < max_r and min_c < c < max_c:
                result[r][c] = 8

    return result
